sys_variable_value.value:
(function execute(inputs, outputs) {

    outputs.is_called = false;

    var queue = inputs.queue_record;

    if (!queue || !queue.isValidRecord()) {
        return;
    }

    var queueId = queue.getUniqueValue();

    var gr = new GlideRecord('x_snc_queuesmart_queue');

    if (gr.get(queueId)) {
        outputs.is_called = (gr.getValue('status') == 'called');
    }

})(inputs, outputs);

